const MAX_IMAGE_BYTES = 25 * 1024 * 1024;
const MAX_UPLOAD_BYTES = 10 * 1024 * 1024;

async function optimizeImage(file) {
  if (!file) return file;
  if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
    throw new Error('Choose a JPG, PNG, or WebP image.');
  }
  if (file.size > MAX_IMAGE_BYTES) {
    throw new Error('Choose an image smaller than 25 MB.');
  }

  const image = new Image();
  const objectUrl = URL.createObjectURL(file);
  try {
    image.src = objectUrl;
    await image.decode();
    const scale = Math.min(1, 2400 / Math.max(image.naturalWidth, image.naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
    const context = canvas.getContext('2d');
    if (!context) return file;
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    let bestBlob = null;
    for (const quality of [0.82, 0.7, 0.58, 0.46]) {
      const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', quality));
      if (!blob) break;
      if (!bestBlob || blob.size < bestBlob.size) bestBlob = blob;
      if (blob.size <= MAX_UPLOAD_BYTES) {
        if (file.size <= MAX_UPLOAD_BYTES && blob.size >= file.size) return file;
        const stem = file.name.replace(/\.[^.]+$/, '') || 'image';
        return new File([blob], `${stem}.webp`, { type: 'image/webp', lastModified: Date.now() });
      }
    }
    if (file.size <= MAX_UPLOAD_BYTES) return file;
    if (!bestBlob || bestBlob.size > MAX_UPLOAD_BYTES) {
      throw new Error('Image is still larger than the 10 MB upload limit after compression. Choose a smaller image.');
    }
    const stem = file.name.replace(/\.[^.]+$/, '') || 'image';
    return new File([bestBlob], `${stem}.webp`, { type: 'image/webp', lastModified: Date.now() });
  } catch {
    throw new Error(`Could not read ${file.name}. Use a valid JPG, PNG, or WebP image.`);
  } finally {
    URL.revokeObjectURL(objectUrl);
  }
}
