function App(){
  const [token,setToken]=useState(()=>sessionStorage.getItem('yomart_admin_token')||'');
  const [user,setUser]=useState(null); const [authLoading,setAuthLoading]=useState(Boolean(token));
  const [page,setPage]=useState('dashboard'); const [theme,setTheme]=useState(()=>localStorage.getItem('yomart_admin_theme')||'dark');
  const [menuOpen,setMenuOpen]=useState(false); const [notice,setNotice]=useState(null); const [refresh,setRefresh]=useState(0);
  const noticeTimer=useRef(null);
  const showNotice=(text,type='success')=>{if(noticeTimer.current)window.clearTimeout(noticeTimer.current);setNotice({text,type});noticeTimer.current=window.setTimeout(()=>setNotice(null),4200)};
  useEffect(()=>()=>{if(noticeTimer.current)window.clearTimeout(noticeTimer.current)},[]);
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('yomart_admin_theme',theme)},[theme]);
  useEffect(()=>{if(!token){setUser(null);setAuthLoading(false);return}let live=true;request('/admin-users/profile',{token}).then(r=>{if(live)setUser(r.data)}).catch(()=>{if(live){sessionStorage.removeItem('yomart_admin_token');setToken('')}}).finally(()=>live&&setAuthLoading(false));return()=>{live=false}},[token]);
  const logout=()=>{sessionStorage.removeItem('yomart_admin_token');setToken('');setUser(null)};
  if(authLoading)return <div className="boot"><img className="brand-logo" src="/yomart_gold_mark.png" alt="YoMart"/><span className="spinner"/>Checking admin session…</div>;
  if(!token||!user)return <Login onLogin={(t,u)=>{sessionStorage.setItem('yomart_admin_token',t);setToken(t);setUser(u)}}/>;
  const allowed=NAV.filter(item=>(!item.superOnly||user.clearanceLevel==='super_admin')&&(!item.adminOnly||['admin','super_admin'].includes(user.clearanceLevel))&&!(item.id==='orders'&&user.clearanceLevel==='moderator'));
  const current=allowed.find(n=>n.id===page)||allowed[0];
  const activePage=current.id;
  return <div className="app-shell" data-theme={theme}>
    <aside className={`sidebar ${menuOpen?'open':''}`}>
      <div className="brand"><img className="brand-logo" src="/yomart_gold_mark.png" alt="YoMart"/><div><b>YoMart</b><small>ADMIN CONSOLE</small></div><button className="icon-button mobile-close" onClick={()=>setMenuOpen(false)}><X size={18}/></button></div>
      <div className="workspace"><span className="workspace-dot"/><div><b>Store workspace</b><small>Live catalog</small></div><ChevronDown size={15}/></div>
      <div className="nav-caption">WORKSPACE</div><nav className="nav-list">{allowed.map(item=>{const Icon=item.icon;return <button key={item.id} className={`nav-item ${activePage===item.id?'active':''}`} onClick={()=>{setPage(item.id);setMenuOpen(false)}}><Icon size={18}/><span>{item.label}</span>{item.id==='orders'&&<span className="nav-dot"/>}</button>})}</nav>
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><CircleHelp size={17}/></div><b>Need a hand?</b><p>Get help managing your store.</p><button onClick={()=>showNotice('Contact your platform administrator for support.','info')}>Open support <ChevronRight size={14}/></button></div><div className="profile-mini"><div className="avatar">{(user.name||user.username||'A').slice(0,1).toUpperCase()}</div><div className="profile-copy"><b>{user.name||user.username}</b><small>{label(user.clearanceLevel||'admin')}</small></div><button className="icon-button" title="Sign out" onClick={logout}><LogOut size={16}/></button></div></div>
    </aside>
    {menuOpen&&<button className="mobile-scrim" aria-label="Close menu" onClick={()=>setMenuOpen(false)}/>}
    <main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setMenuOpen(true)}><Menu size={20}/></button><div className="top-actions"><button className="icon-button" title="Toggle theme" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={18}/>:<Moon size={18}/>}</button><button className="icon-button notification" title="Notifications" onClick={()=>showNotice('Notifications are not configured for this workspace yet.','info')}><Bell size={18}/></button><div className="top-avatar">{(user.name||user.username||'A').slice(0,1).toUpperCase()}</div></div></header>
      <div className="content-wrap"><div className="page-heading"><div><h1>{current.id==='dashboard'?'Store overview':current.label}</h1><p>{pageDescription(activePage)}</p></div>{activePage==='dashboard'&&<div className="heading-actions"><button className="button secondary" onClick={()=>setRefresh(x=>x+1)}><RefreshCw size={15}/> Refresh</button></div>}</div>
      {activePage==='dashboard'?(user.clearanceLevel==='moderator'?<ModeratorDashboard token={token} refresh={refresh} setPage={setPage}/>:<Dashboard token={token} refresh={refresh} setPage={setPage}/>):activePage==='settings'?<SettingsPage setPage={setPage}/>:activePage==='payment-methods'?<PaymentMethodsManager api={API} token={token} refresh={refresh} notify={showNotice}/>:activePage==='stories'?<StoryManager api={API} token={token} refresh={refresh} notify={showNotice}/>:activePage==='retailer-contacts'?<RetailerContactsManager api={API} token={token} refresh={refresh} notify={showNotice}/>:<ResourcePage key={activePage} type={activePage} token={token} refresh={refresh} notify={showNotice} user={user}/>}
      </div><footer className="footer"><span>YoMart Admin</span><span>Secure store management <i>·</i> {API}</span></footer>
    </main>{notice&&<div className={`toast ${notice.type}`} role="status" aria-live="polite">{notice.type==='error'?<AlertCircle size={17}/>:notice.type==='info'?<Activity size={17}/>:<CheckCircle2 size={17}/>}<span>{notice.text}</span><button onClick={()=>setNotice(null)} aria-label="Dismiss message"><X size={15}/></button></div>}
  </div>
}
function singular(s){return ({Products:'product',Categories:'category',Subcategories:'subcategory',Brands:'brand',Banners:'banner',Collections:'collection','Admin users':'admin user'})[s]||s}
function pageDescription(p){return ({dashboard:'A clear view of catalog, orders, and store activity.',products:'Manage product details, images, pricing, and availability.',categories:'Organize the categories customers browse in the store.',subCategories:'Manage the subcategories used by products and brands.',brands:'Control brand names and the category they belong to.',posters:'Manage the promotional banners displayed in the storefront.',stories:'Upload, preview, and publish customer video stories.',collections:'Curate product groups shown to customers.',orders:'Review purchases, update fulfillment, and verify payments.',settings:'Manage fulfillment settings.', 'payment-methods':'Configure the manual payment options customers can use at checkout.', 'retailer-contacts':'Manage contact options displayed to YoMart customers.',admins:'Manage accounts allowed to access the admin console.'})[p]||'Manage your store content.'}

function Login({onLogin}){const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[show,setShow]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError('');try{const r=await request('/admin-users/login',{method:'POST',body:{username,password}});onLogin(r.data.token,r.data.user)}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="login-screen"><section className="login-art"><div className="orb orb-a"/><div className="orb orb-b"/><div className="brand login-art-brand"><img className="brand-logo" src="/yomart_gold_mark.png" alt="YoMart"/><div><b>YoMart</b><small>ADMIN DASHBOARD</small></div></div><div className="login-pitch"><div className="eyebrow">YOUR STORE, IN ONE PLACE</div><h1>Manage your store<br/><em>with confidence.</em></h1><p>Products, orders, and storefront updates, all in one workspace.</p><div className="pitch-tags"><span><Shield size={14}/> Secure access</span><span><Activity size={14}/> Live store data</span></div></div><div className="login-foot">YoMart · Store management</div></section><section className="login-panel"><div className="login-card"><div className="eyebrow">WELCOME BACK</div><h2>Sign in to your workspace</h2><p>Enter your administrator account details.</p>{error&&<div className="form-error" role="alert" aria-live="polite"><AlertCircle size={16}/><span>{error}</span></div>}<form onSubmit={submit}><label className={"login-floating "+(username?'filled':'')}><Users size={17}/><input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} placeholder=" " required/><span>Username</span></label><label className={"login-floating "+(password?'filled':'')}><Shield size={17}/><input type={show?'text':'password'} autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder=" " required/><span>Password</span><button type="button" className="password-toggle" onClick={()=>setShow(!show)} aria-label={show?'Hide password':'Show password'}>{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></label><button className="button primary login-submit" disabled={busy}>{busy?<><span className="small-spinner"/> Signing in…</>:<>Sign in <ChevronRight size={17}/></>}</button></form><div className="login-security"><Shield size={15}/> Administrator access is protected.</div></div></section></div>}


function ModeratorDashboard({token,refresh,setPage}){const [data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);useEffect(()=>{let live=true;setLoading(true);Promise.allSettled([request('/products',{token}),request('/categories',{token})]).then(results=>{if(!live)return;setData({products:results[0].status==='fulfilled'?readPayload(results[0].value):[],categories:results[1].status==='fulfilled'?readPayload(results[1].value):[]});const failures=results.filter(x=>x.status==='rejected');if(failures.length)setError(failures[0].reason.message)}).finally(()=>live&&setLoading(false));return()=>{live=false}},[token,refresh]);return <div className="dashboard">{error&&<div className="inline-alert" role="alert"><AlertCircle size={17}/>{error}</div>}<div className="stats-grid">{[['My products',data?.products.length??'—',Package],['Categories',data?.categories.length??'—',Boxes],['Low stock',data?.products.filter(p=>Number(p.quantity||0)<=5).length??'—',AlertCircle]].map(([title,value,Icon])=><div className="stat-card" key={title}><div className="stat-top"><span>{title}</span><div className="stat-icon"><Icon size={18}/></div></div><strong>{loading?<span className="skeleton-text"/>:value}</strong><small>Catalog records available to your account</small></div>)}</div><section className="panel"><div className="panel-heading"><div><h2>Catalog workspace</h2><p>Manage catalog records available to your account.</p></div></div><button className="button primary" onClick={()=>setPage('products')}>Manage products <ChevronRight size={15}/></button></section></div>}

function Dashboard({token,refresh,setPage}){const [data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);useEffect(()=>{let active=true;setLoading(true);setError('');Promise.allSettled([request('/products',{token}),request('/orders',{token}),request('/categories',{token}),request('/users',{token})]).then(results=>{if(!active)return;const failures=results.filter(x=>x.status==='rejected');setData({products:results[0].status==='fulfilled'?readPayload(results[0].value):[],orders:results[1].status==='fulfilled'?readPayload(results[1].value):[],categories:results[2].status==='fulfilled'?readPayload(results[2].value):[],customers:results[3].status==='fulfilled'?readPayload(results[3].value):[]});if(failures.length)setError(failures.length===4?failures[0].reason.message:`Some dashboard data sources are unavailable (${failures.length} of 4). Totals may be incomplete.`)}).finally(()=>active&&setLoading(false));return()=>{active=false}},[token,refresh]);
  const counts=useMemo(()=>{if(!data)return null;return {sales:data.orders.reduce((a,o)=>a+Number(o.orderTotal?.total??o.totalPrice??0),0),orders:data.orders.length,products:data.products.length,categories:data.categories.length,low:data.products.filter(p=>Number(p.quantity||0)<=5).length,customers:data.customers.length}},[data]);
  const series=useMemo(()=>{if(!data)return[];const map=new Map();for(const o of data.orders){const d=new Date(o.orderDate||o.createdAt||Date.now());if(Number.isNaN(d.getTime()))continue;const k=d.toLocaleDateString(undefined,{month:'short',day:'numeric'});map.set(k,(map.get(k)||0)+Number(o.orderTotal?.total??o.totalPrice??0))}return [...map].slice(-8).map(([date,sales])=>({date,sales}))},[data]);
  return <div className="dashboard"><div className="stats-grid">{[['Sales total',counts?money(counts.sales):'—',WalletCards,'var(--blue)','Orders in current dataset'],['Total orders',counts?.orders??'—',ShoppingCart,'var(--cyan)','All recorded orders'],['Total products',counts?.products??'—',Box,'var(--violet)','Catalog items'],['Low stock',counts?.low??'—',AlertCircle,'var(--red)','5 units or fewer']].map(([title,value,Icon,color,sub])=><div className="stat-card" key={title}><div className="stat-top"><span>{title}</span><div className="stat-icon" style={{'--stat':color}}><Icon size={18}/></div></div><strong>{loading?<span className="skeleton-text"/>:value}</strong><small>{sub}</small></div>)}</div>
    {error&&<div className="inline-alert"><AlertCircle size={17}/>{error}<button onClick={()=>location.reload()}>Retry</button></div>}
    {!loading&&data&&data.orders.length===0&&<div className="dashboard-note"><Activity size={16}/><span><b>Reports are connected to live orders.</b> There are no order records yet, so sales and order reports will fill in after the first customer purchase.</span><button onClick={()=>setPage('orders')}>Open orders <ChevronRight size={14}/></button></div>}
    <div className="dashboard-grid"><section className="panel sales-panel"><div className="panel-heading"><div><h2>Sales overview</h2><p>Order totals from the data currently in your store.</p></div><span className="period-pill">All recorded orders <ChevronDown size={13}/></span></div>{loading?<div className="chart-empty"><span className="spinner"/> Loading sales…</div>:!series.length?<EmptyState icon={WalletCards} title="No sales data yet" description="Sales will appear here after customers place orders."/>:<><div className="chart-total">{money(counts.sales)}<small> across {counts.orders} orders</small></div><SalesChart series={series}/></>}</section>
      <section className="panel activity-panel"><div className="panel-heading"><div><h2>Recent orders</h2><p>Latest customer activity</p></div><button className="text-link" onClick={()=>setPage('orders')}>View all <ChevronRight size={14}/></button></div>{loading?<div className="chart-empty"><span className="spinner"/></div>:!data?.orders.length?<EmptyState icon={Activity} title="No recent orders" description="New orders will be listed here."/>:<div className="activity-list">{data.orders.slice(0,5).map(o=><div className="activity-row" key={idOf(o)}><div className="activity-glyph"><ShoppingBag size={16}/></div><div className="activity-copy"><b>Order #{String(idOf(o)||'').slice(-7).toUpperCase()}</b><small>{o.userID?.name||o.userID?.email||'Customer'} · {formatDate(o.orderDate||o.createdAt)}</small></div><div className="activity-amount">{money(o.orderTotal?.total??o.totalPrice)}<Status value={o.orderStatus}/></div></div>)}</div>}</section>
      <section className="panel top-products"><div className="panel-heading"><div><h2>Catalog snapshot</h2><p>Items currently available in your catalog</p></div><button className="text-link" onClick={()=>setPage('products')}>Manage products <ChevronRight size={14}/></button></div>{loading?<div className="chart-empty"><span className="spinner"/></div>:!data?.products.length?<EmptyState icon={Package} title="Your catalog is empty" description="Add products to make them available in the storefront." action={()=>setPage('products')}/> :<div className="mini-products">{data.products.slice(0,4).map(p=><div className="mini-product" key={idOf(p)}><ProductThumb item={p}/><div><b>{p.name}</b><small>{money(p.offerPrice||p.price)} · {p.quantity??0} in stock</small></div><Status value={p.isActive===false?'hidden':'active'}/></div>)}</div>}</section>
      <section className="panel quick-panel"><div className="panel-heading"><div><h2>Store snapshot</h2><p>Current live records</p></div><Store size={18} className="muted-icon"/></div><div className="snapshot-list">{[['Categories',counts?.categories??'—',Boxes],['Customers',counts?.customers??'—',Users],['Orders needing payment review',data?.orders.filter(o=>o.paymentStatus==='pending'&&(orderNeedsPaymentProof(o)?Boolean(o.paymentProof?.available):true)).length??'—',CreditCard]].map(([n,v,I])=><div key={n}><span className="snapshot-icon"><I size={16}/></span><span>{n}</span><b>{loading?'…':v}</b></div>)}</div><div className="secure-note"><Shield size={15}/> Values come from the connected store API.</div></section></div>
  </div>}
function formatDate(x){const d=new Date(x);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function SalesChart({series}){const width=760,height=195,pad={left:12,right:12,top:13,bottom:28};const max=Math.max(1,...series.map(x=>x.sales));const points=series.map((x,i)=>({x:pad.left+(series.length===1?0:i*(width-pad.left-pad.right)/(series.length-1)),y:pad.top+(height-pad.top-pad.bottom)*(1-x.sales/max),...x}));const line=points.map((p,i)=>`${i?'L':'M'} ${p.x} ${p.y}`).join(' ');const area=`${line} L ${points.at(-1)?.x||0} ${height-pad.bottom} L ${points[0]?.x||0} ${height-pad.bottom} Z`;return <div className="chart"><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" role="img" aria-label="Sales by order date"><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2689ff" stopOpacity=".34"/><stop offset="95%" stopColor="#2689ff" stopOpacity="0"/></linearGradient></defs>{[0,1,2,3].map(i=>{const y=pad.top+(height-pad.top-pad.bottom)*i/3;return <line key={i} x1={pad.left} y1={y} x2={width-pad.right} y2={y} stroke="var(--chart-grid)" strokeDasharray="4 5"/>})}<path d={area} fill="url(#salesFill)"/><path d={line} fill="none" stroke="#2689ff" strokeWidth="3" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round"/>{points.map((p,i)=><g key={`${p.date}-${i}`}><circle cx={p.x} cy={p.y} r="3.3" fill="var(--surface)" stroke="#4a9dff" strokeWidth="2"/><text x={p.x} y={height-7} textAnchor={i===0?'start':i===points.length-1?'end':'middle'} fill="var(--muted)" fontSize="10">{p.date}</text></g>)}</svg></div>}
function Status({value}){const v=String(value??'unknown').toLowerCase().replaceAll('_',' ');return <span className={`status status-${v.replaceAll(' ','-')}`}>{v}</span>}
function ProductThumb({item}){const url=mediaUrl(item?.images?.[0]?.url);return <div className="product-thumb">{url?<img src={url} alt={item?.name||'Product'} loading="lazy"/>:<Package size={18}/>}</div>}
function MediaThumb({url,alt}){const [failed,setFailed]=useState(false);const resolved=mediaUrl(url);return <div className="product-thumb media-thumb">{resolved&&!failed?<img src={resolved} alt={alt||''} loading="lazy" onError={()=>setFailed(true)}/>:<ImageIcon size={17}/>}</div>}
function EmptyState({icon:Icon,title,description,action}){return <div className="empty-state"><div className="empty-icon"><Icon size={20}/></div><b>{title}</b><p>{description}</p>{action&&<button className="button secondary" onClick={action}>Open catalog <ChevronRight size={15}/></button>}</div>}

function ResourcePage({type,token,refresh,notify,user}){const config=resourceConfig[type];const [rows,setRows]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[query,setQuery]=useState(''),[modal,setModal]=useState(null);const [related,setRelated]=useState({});
  const load=()=>{setLoading(true);setError('');request(config.endpoint,{token}).then(r=>setRows(readPayload(r))).catch(e=>setError(e.message)).finally(()=>setLoading(false))};
  useEffect(()=>{load()},[type,token,refresh]);
  useEffect(()=>{if(type==='products'||type==='categories'||type==='subCategories'||type==='brands'||type==='collections'){Promise.allSettled([request('/categories',{token}),request('/subCategories',{token}),request('/brands',{token}),request('/products',{token})]).then(([c,s,b,p])=>setRelated({categories:c.status==='fulfilled'?readPayload(c.value):[],subCategories:s.status==='fulfilled'?readPayload(s.value):[],brands:b.status==='fulfilled'?readPayload(b.value):[],products:p.status==='fulfilled'?readPayload(p.value):[]}))}},[type,token]);
  useEffect(()=>{const f=()=>setModal({});window.addEventListener('admin-create',f);return()=>window.removeEventListener('admin-create',f)},[]);
  const filtered=rows.filter(row=>!query||config.searchable.some(k=>String(plain(row[k])??'').toLowerCase().includes(query.toLowerCase())));
  const edit=(row)=>setModal(row||{});
  const remove=async row=>{if(!confirm(`Delete this ${singular(config.title)}?`))return;try{await request(`${config.endpoint}/${idOf(row)}`,{token,method:'DELETE'});notify(`${singular(config.title)} deleted.`);load()}catch(e){notify(e.message,'error')}};
  return <section className="panel resource-panel"><div className="resource-toolbar"><div className="table-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${config.title.toLowerCase()}…`}/>{query&&<button onClick={()=>setQuery('')}><X size={14}/></button>}</div><div className="toolbar-right"><span className="result-count">{loading?'Loading…':`${filtered.length} ${filtered.length===1?'record':'records'}`}</span><button className="icon-button" onClick={load} title="Reload"><RefreshCw size={16}/></button>{config.create&&<button className="button primary" onClick={()=>edit(null)}><Plus size={16}/> Add {singular(config.title)}</button>}</div></div>
    {error?<div className="resource-error"><AlertCircle size={20}/><b>Could not load {config.title.toLowerCase()}</b><p>{error}</p><button className="button secondary" onClick={load}><RefreshCw size={14}/> Try again</button></div>:loading?<div className="table-loading"><span className="spinner"/>Loading live data…</div>:!filtered.length?<EmptyState icon={config.icon} title={query?'No matching records':`No ${config.title.toLowerCase()} yet`} description={query?'Try another search term.':`Records added to your store will appear here.`} action={config.create?()=>edit(null):undefined}/>:<div className="table-scroll"><table><thead><tr>{type==='products'&&<th>Image</th>}{config.columns.map(col=><th key={col}>{['image','logoUrl','imageUrl'].includes(col)?'Image':label(col)}</th>)}<th>Updated</th><th className="actions-head">Actions</th></tr></thead><tbody>{filtered.map(row=><tr key={idOf(row)}>{type==='products'&&<td><ProductThumb item={row}/></td>}{config.columns.map(col=><td key={col}>{renderCell(row,col,type)}</td>)}<td className="date-cell">{formatDate(row.updatedAt||row.createdAt||row.orderDate)}</td><td><div className="row-actions">{type==='orders'?<button title="View details" onClick={()=>edit(row)} className="icon-button"><Eye size={15}/></button>:<button title="Edit" onClick={()=>edit(row)} className="icon-button"><Pencil size={15}/></button>}{type!=='orders'&&<button title="Delete" onClick={()=>remove(row)} className="icon-button danger-hover"><Trash2 size={15}/></button>}</div></td></tr>)}</tbody></table></div>}
    {modal&&<RecordModal type={type} item={modal} token={token} related={related} notify={notify} close={()=>setModal(null)} saved={()=>{setModal(null);load()}} user={user}/>}
  </section>
}
function renderCell(row,key,type){const val=row[key];if(['image','logoUrl','imageUrl'].includes(key))return <MediaThumb url={val} alt={row.name||row.posterName||'Catalog image'}/>;if(key==='isActive')return <Status value={val?'active':'hidden'}/>;if(key==='isSearchVerified')return <Status value={val?'verified':'not-verified'}/>;if(key==='orderStatus'||key==='paymentStatus')return <Status value={val}/>;if(key==='price'||key==='totalPrice')return <b className="price-cell">{money(key==='price'?(row.offerPrice||val):val)}</b>;if(key==='quantity')return <span className={Number(val)<=5?'low-stock':''}>{val??0} units</span>;if(key==='productIds'||key==='items')return <span className="count-pill">{val?.length||0} {key==='items'?'items':'products'}</span>;if(key==='orderDate')return formatDate(val);return <span className="cell-text" title={String(plain(val)??'')}>{plain(val)??'—'}</span>}

function RecordModal({type,item,token,related,notify,close,saved,user}){const isEdit=Boolean(idOf(item));const [form,setForm]=useState(()=>({...item})),[busy,setBusy]=useState(false),[error,setError]=useState(''),[files,setFiles]=useState({});const cfg=resourceConfig[type];const change=(k,v)=>setForm(x=>({...x,[k]:v}));
  useEffect(()=>{const key=e=>e.key==='Escape'&&close();window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[close]);
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{let body=form;let headersBody=true;
    if(type==='products'||type==='categories'||type==='posters'||type==='brands'){
      body=new FormData();Object.entries(form).forEach(([k,v])=>{if(['_id','__v','createdAt','updatedAt','createdBy','images','id'].includes(k)||v===undefined||v===null||typeof v==='object')return;body.append(k,typeof v==='boolean'?String(v):String(v))});
      if(type==='products'){for(let i=1;i<=5;i++)if(files[`image${i}`])body.append(`image${i}`,await optimizeImage(files[`image${i}`]));if(Array.isArray(form.proVariantId))body.set('proVariantId',form.proVariantId.join(','));}
      if(type==='categories'&&files.img)body.append('img',await optimizeImage(files.img));if(type==='posters'&&files.img)body.append('img',await optimizeImage(files.img));if(type==='posters'&&isEdit&&!files.img)body.set('image',form.imageUrl||'');if(type==='brands'&&files.logo)body.append('logo',await optimizeImage(files.logo));
      if(type==='products'){if(!isEdit&&!Object.keys(files).some(k=>k.startsWith('image')))throw new Error('Add at least one product image.');}
      if(type==='categories'&&!isEdit&&!files.img)throw new Error('Choose a category image.');if(type==='posters'&&!isEdit&&!files.img)throw new Error('Choose a banner image.');
    }else if(type==='collections'){body={...form,productIds:Array.isArray(form.productIds)?form.productIds:(form.productIds||'').split(',').map(s=>s.trim()).filter(Boolean),sortOrder:Number(form.sortOrder||0),isActive:form.isActive!==false}}
    else if(type==='admins'&&!isEdit){if(user.clearanceLevel!=='super_admin')throw new Error('Only a super admin can add admin accounts.');body={...form}}
    else if(type==='orders'){
      if(form.__action==='verify'||form.__action==='reject'){await request(`${cfg.endpoint}/${idOf(item)}/verify-payment`,{token,method:'PUT',body:{verified:form.__action==='verify'}})}else await request(`${cfg.endpoint}/${idOf(item)}`,{token,method:'PUT',body:orderUpdatePayload(form)});
      notify('Order updated successfully.');saved();return;
    }
    await request(`${cfg.endpoint}${isEdit?`/${idOf(item)}`:''}`,{token,method:isEdit?'PUT':'POST',body});notify(`${singular(cfg.title)} ${isEdit?'updated':'created'}.`);saved();
  }catch(err){setError(err.message)}finally{setBusy(false)}};
  const verifyPayment=async verified=>{setBusy(true);setError('');try{await request(`${cfg.endpoint}/${idOf(item)}/verify-payment`,{token,method:'PUT',body:{verified}});notify(verified?'Payment verified.':'Payment rejected.');saved()}catch(err){setError(err.message)}finally{setBusy(false)}};
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className={`modal ${type==='orders'?'wide-modal':''}`}><div className="modal-head"><div><div className="eyebrow">{type==='orders'?'ORDER MANAGEMENT':isEdit?'EDIT RECORD':'NEW RECORD'}</div><h2>{type==='orders'?`Order #${String(idOf(item)).slice(-8).toUpperCase()}`:`${isEdit?'Edit':'Add'} ${singular(cfg.title)}`}</h2></div><button className="icon-button" onClick={close}><X size={18}/></button></div><form onSubmit={submit}><div className="modal-body">{error&&<div className="form-error"><AlertCircle size={15}/>{error}</div>}{type==='products'?<ProductForm form={form} change={change} related={related} files={files} setFiles={setFiles}/>:type==='categories'?<><Field label="Category name" required><input value={form.name||''} onChange={e=>change('name',e.target.value)} required maxLength={80}/></Field><ImageUpload label="Category image" file={files.img} current={form.image} onChange={f=>setFiles(x=>({...x,img:f}))}/><Field label="Sort order"><input type="number" min="0" value={form.sortOrder??0} onChange={e=>change('sortOrder',Number(e.target.value))}/></Field><Toggle label="Visible in storefront" value={form.isActive!==false} onChange={v=>change('isActive',v)}/></>:type==='subCategories'?<><Field label="Subcategory name" required><input value={form.name||''} onChange={e=>change('name',e.target.value)} required/></Field><Field label="Parent category" required><select value={refId(form.categoryId)} onChange={e=>change('categoryId',e.target.value)} required><option value="">Select category</option>{related.categories.map(x=><option key={idOf(x)} value={idOf(x)}>{x.name}</option>)}</select></Field></>:type==='brands'?<><Field label="Brand name" required><input value={form.name||''} onChange={e=>change('name',e.target.value)} required maxLength={80}/></Field><Field label="Subcategory" hint="Optional; a brand can be used across several product categories."><select value={refId(form.subcategoryId)} onChange={e=>change('subcategoryId',e.target.value)}><option value="">All product categories</option>{related.subCategories.map(x=><option key={idOf(x)} value={idOf(x)}>{x.name}</option>)}</select></Field><ImageUpload label="Brand logo" file={files.logo} current={form.logoUrl} onChange={f=>setFiles(x=>({...x,logo:f}))}/><Field label="Sort order"><input type="number" min="0" value={form.sortOrder??0} onChange={e=>change('sortOrder',Number(e.target.value))}/></Field><Toggle label="Visible in storefront" value={form.isActive!==false} onChange={v=>change('isActive',v)}/></>:type==='posters'?<><Field label="Banner title" required><input value={form.posterName||''} onChange={e=>change('posterName',e.target.value)} required maxLength={100}/></Field><Field label="Subtitle"><input value={form.subtitle||''} onChange={e=>change('subtitle',e.target.value)} maxLength={160}/></Field><ImageUpload label="Banner image" file={files.img} current={form.imageUrl} onChange={f=>setFiles(x=>({...x,img:f}))}/><Field label="Sort order"><input type="number" min="0" value={form.sortOrder??0} onChange={e=>change('sortOrder',Number(e.target.value))}/></Field><Toggle label="Visible in storefront" value={form.isActive!==false} onChange={v=>change('isActive',v)}/></>:type==='collections'?<><Field label="Collection title" required><input value={form.title||''} onChange={e=>change('title',e.target.value)} required maxLength={80}/></Field><Field label="Subtitle" required><input value={form.subtitle||''} onChange={e=>change('subtitle',e.target.value)} required maxLength={140}/></Field><Field label="Products" hint="Select one or more products to curate this collection."><select multiple className="multi-select" value={Array.isArray(form.productIds)?form.productIds.map(refId):[]} onChange={e=>change('productIds',[...e.target.selectedOptions].map(o=>o.value))}>{related.products.map(x=><option key={idOf(x)} value={idOf(x)}>{x.name}</option>)}</select></Field><Field label="Sort order"><input type="number" min="0" value={form.sortOrder??0} onChange={e=>change('sortOrder',Number(e.target.value))}/></Field><Toggle label="Visible in storefront" value={form.isActive!==false} onChange={v=>change('isActive',v)}/></>:type==='admins'?<AdminForm form={form} change={change} isEdit={isEdit}/>:<OrderForm item={item} form={form} change={change} token={token}/> }</div><div className="modal-actions"><button type="button" className="button secondary" onClick={close}>Cancel</button>{type==='orders'?<><button type="submit" className="button primary" disabled={busy}><Check size={15}/> Save order</button>{item.paymentStatus==='pending'&&(!orderNeedsPaymentProof(item)||item.paymentProof?.available)&&<><button type="button" className="button secondary" disabled={busy} onClick={()=>verifyPayment(false)}>Reject proof</button><button type="button" className="button success" disabled={busy} onClick={()=>verifyPayment(true)}>Verify payment</button></>}</>:<button type="submit" className="button primary" disabled={busy}>{busy?<><span className="small-spinner"/> Saving…</>:<><Check size={15}/> {isEdit?'Save changes':'Create record'}</>}</button>}</div></form></div></div>
}
function refId(v){return v&&typeof v==='object'?idOf(v):v||''}
function Field({label,children,required,hint}){return <label className="field"><span>{label}{required&&<i> *</i>}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Toggle({label,value,onChange}){return <div className="toggle-row"><span>{label}</span><button type="button" className={`toggle ${value?'on':''}`} onClick={()=>onChange(!value)}><i/></button></div>}
function ImageUpload({label,file,current,onChange}){return <Field label={label}><label className="upload-zone"><input type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" onChange={e=>onChange(e.target.files?.[0])}/>{file?<><CheckCircle2 size={20}/><b>{file.name}</b><small>{(file.size/1024/1024).toFixed(1)} MB</small></>:current?<><img src={mediaUrl(current)} alt="Current image"/><span>Choose to replace current image</span></>:<><Upload size={20}/><b>Choose image</b><small>Compressed before upload; the server also normalizes stored images.</small></>}</label></Field>}
function ProductForm({form,change,related,files,setFiles}){return <><Field label="Product name" required><input value={form.name||''} onChange={e=>change('name',e.target.value)} required maxLength={100}/></Field><Field label="Description"><textarea value={form.description||''} onChange={e=>change('description',e.target.value)} maxLength={1000} rows="3"/></Field><div className="form-grid"><Field label="Price (Birr)" required><input type="number" min="0" step="0.01" value={form.price??''} onChange={e=>change('price',e.target.value)} required/></Field><Field label="Offer price"><input type="number" min="0" step="0.01" value={form.offerPrice??''} onChange={e=>change('offerPrice',e.target.value)}/></Field><Field label="Stock quantity" required><input type="number" min="0" value={form.quantity??''} onChange={e=>change('quantity',e.target.value)} required/></Field><Field label="Sort order"><input type="number" min="0" value={form.sortOrder??0} onChange={e=>change('sortOrder',e.target.value)}/></Field></div><div className="form-grid"><Field label="Category" required><select value={refId(form.proCategoryId)} onChange={e=>change('proCategoryId',e.target.value)} required><option value="">Select category</option>{related.categories.map(x=><option key={idOf(x)} value={idOf(x)}>{x.name}</option>)}</select></Field><Field label="Subcategory" required><select value={refId(form.proSubCategoryId)} onChange={e=>change('proSubCategoryId',e.target.value)} required><option value="">Select subcategory</option>{related.subCategories.filter(x=>!form.proCategoryId||refId(x.categoryId)===refId(form.proCategoryId)).map(x=><option key={idOf(x)} value={idOf(x)}>{x.name}</option>)}</select></Field></div><Field label="Brand"><select value={refId(form.proBrandId)} onChange={e=>change('proBrandId',e.target.value)}><option value="">No brand</option>{related.brands.map(x=><option key={idOf(x)} value={idOf(x)}>{x.name}</option>)}</select></Field><div className="image-slots"><div className="section-kicker">Product images <small>Up to five images, each can be replaced.</small></div>{[1,2,3,4,5].map(n=><label className="image-slot" key={n}><input type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" onChange={e=>setFiles(x=>({...x,[`image${n}`]:e.target.files?.[0]}))}/>{files[`image${n}`]?<><CheckCircle2 size={16}/><span>{files[`image${n}`].name}</span></>:form.images?.find(x=>x.image===n)?.url?<><img src={mediaUrl(form.images.find(x=>x.image===n).url)} alt=""/><span>Image {n}</span></>:<><Plus size={17}/><span>Image {n}</span></>}</label>)}</div>{form.catalogSource&&<div className="inline-alert"><AlertCircle size={16}/><span>Reference price from {form.catalogSource.retailer||'external catalog'}; checked {formatDate(form.catalogSource.checkedAt)}. Confirm YoMart pricing and stock before accepting orders. <a href={form.catalogSource.productUrl} target="_blank" rel="noreferrer">View source listing</a></span></div>}<Toggle label="Verified for public search" value={form.isSearchVerified===true} onChange={v=>change('isSearchVerified',v)}/><p className="field-hint">Enable only after confirming the exact product, photos, selling price, and stock; remove any sample or reference wording from its description first. It publishes the listing to search engines after the next web build.</p><Toggle label="Available in storefront" value={form.isActive!==false} onChange={v=>change('isActive',v)}/></>}
function AdminForm({form,change,isEdit}){return <><Field label="Full name" required><input value={form.name||''} onChange={e=>change('name',e.target.value)} required/></Field><Field label="Username" required><input value={form.username||''} onChange={e=>change('username',e.target.value)} required disabled={isEdit}/></Field><Field label="Email address" required><input type="email" value={form.email||''} onChange={e=>change('email',e.target.value)} required/></Field><Field label={isEdit?'New password (optional)':'Temporary password'} required={!isEdit}><input type="password" minLength="12" value={form.password||''} onChange={e=>change('password',e.target.value)} required={!isEdit}/></Field>{!isEdit&&<><Field label="Access level"><select value={form.clearanceLevel||'admin'} onChange={e=>change('clearanceLevel',e.target.value)}><option value="admin">Catalog admin</option><option value="moderator">Moderator</option><option value="super_admin">Super admin</option></select></Field><p className="field-hint">Catalog admins and moderators can publish their own catalog records. Super admins can manage all records and team access.</p></>}{isEdit&&<Toggle label="Account enabled" value={form.isActive!==false} onChange={v=>change('isActive',v)}/>}</>}
function AuthorizedProofImage({orderId,token}){const [state,setState]=useState({src:'',error:''});useEffect(()=>{let active=true,objectUrl='';fetch(`${API}/payment/proofs/${encodeURIComponent(orderId)}`,{headers:{Authorization:`Bearer ${token}`}}).then(async response=>{if(!response.ok)throw new Error(response.status===403?'You are not allowed to view this receipt.':'Receipt is unavailable.');const blob=await response.blob();if(!blob.type.startsWith('image/'))throw new Error('Receipt response was not an image.');objectUrl=URL.createObjectURL(blob);if(active)setState({src:objectUrl,error:''})}).catch(error=>{if(active)setState({src:'',error:error.message||'Could not load receipt.'})});return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[orderId,token]);return state.src?<a href={state.src} target="_blank" rel="noreferrer"><img src={state.src} alt="Authorized payment proof"/>View full image <Eye size={14}/></a>:state.error?<p className="proof-error">{state.error}</p>:<p>Loading secure receipt…</p>}
function OrderForm({item,form,change,token}){const point=form.collectionPoint||item.collectionPoint||{};const setPoint=(key,value)=>change('collectionPoint',{...(form.collectionPoint||item.collectionPoint||{}),[key]:value});return <div className="order-detail"><div className="order-summary-row"><div><small>Customer</small><b>{item.userID?.name||item.userID?.email||'Customer'}</b></div><div><small>Placed</small><b>{formatDate(item.orderDate||item.createdAt)}</b></div><div><small>Total</small><b>{money(item.orderTotal?.total??item.totalPrice)}</b></div></div><div className="order-items">{item.items?.map((x,i)=><div key={i}><div className="order-item-icon"><Package size={17}/></div><span><b>{x.productName}</b><small>{x.variant||'Standard'} · Qty {x.quantity}</small></span><strong>{money(x.price* x.quantity)}</strong></div>)}</div><div className="order-summary-row"><div><small>Payment</small><b>{customerOrderPaymentLabel(item)} · {label(item.paymentStatus)}</b>{item.paymentMethodSnapshot?.providerName&&<small>{item.paymentMethodSnapshot.providerName}</small>}{item.paymentMethodSnapshot?.accountHolder&&<small>Recipient: {item.paymentMethodSnapshot.accountHolder}</small>}{item.paymentMethodSnapshot?.accountIdentifier&&<small>Account: {item.paymentMethodSnapshot.accountIdentifier}</small>}{item.paymentMethodSnapshot?.additionalDetails&&<small>{item.paymentMethodSnapshot.additionalDetails}</small>}{item.paymentMethodSnapshot?.instructions&&<small>{item.paymentMethodSnapshot.instructions}</small>}</div><div><small>Customer destination</small><b>{[item.shippingAddress?.phone,item.shippingAddress?.city,item.shippingAddress?.street].filter(Boolean).join(' · ')||'—'}</b>{item.shippingAddress?.latitude!=null&&item.shippingAddress?.longitude!=null&&<small>Coordinates: {item.shippingAddress.latitude}, {item.shippingAddress.longitude}</small>}</div></div><section className="panel order-collection-point"><div className="panel-heading"><div><h3>Agreed collection point</h3><p>Record the location agreed with the customer. Their destination is not this address.</p></div></div>{item.collectionPoint?.name&&item.collectionPoint?.address&&item.collectionPoint?.city&&<p>Currently recorded: <b>{item.collectionPoint.name}</b>, {item.collectionPoint.address}, {item.collectionPoint.city}</p>}<div className="form-grid"><Field label="Collection point name"><input value={point.name||''} onChange={e=>setPoint('name',e.target.value)} maxLength={120} placeholder="Enter agreed point"/></Field><Field label="Collection point address"><input value={point.address||''} onChange={e=>setPoint('address',e.target.value)} maxLength={240} placeholder="Enter agreed address"/></Field><Field label="Collection point city"><input value={point.city||''} onChange={e=>setPoint('city',e.target.value)} maxLength={100}/></Field></div></section>{item.paymentProof?.available&&<div className="proof-box"><b>Payment proof</b><AuthorizedProofImage orderId={idOf(item)} token={token}/></div>}<div className="form-grid"><Field label="Order status"><select value={form.orderStatus||item.orderStatus} onChange={e=>change('orderStatus',e.target.value)}>{ORDER_STATUS_OPTIONS.map(x=><option key={x} value={x}>{label(x)}</option>)}</select></Field><Field label="Tracking reference (optional)"><input type="url" value={form.trackingUrl??item.trackingUrl??''} onChange={e=>change('trackingUrl',e.target.value)} placeholder="https://…"/></Field></div></div>}

function SettingsPage({setPage}){return <div className="settings-layout"><section className="panel settings-panel"><div className="panel-heading"><div><h2>Store operations</h2><p>Fulfillment and customer-facing settings.</p></div><Store size={18} className="muted-icon"/></div><div className="settings-grid"><div className="settings-info-card"><b>Destination-based collection</b><p>Customers provide a destination city for coordination. YoMart staff agree and record the collection point separately. No customer delivery fee is charged.</p></div><div className="settings-info-card"><b>Retailer contacts</b><p>Manage phone, messaging and email contacts in the dedicated section.</p><button className="button secondary" onClick={()=>setPage('retailer-contacts')}>Manage retailer contacts</button></div></div></section><section className="panel settings-panel"><div className="panel-heading"><div><h2>Payment setup</h2><p>Payment options, account details, proof requirements and customer instructions are managed separately.</p></div><CreditCard size={18} className="muted-icon"/></div><p className="field-hint">No bank accounts, wallet identifiers or payment instructions are prefilled by this application. Checkout is unavailable until an active method is configured.</p><button className="button primary" onClick={()=>setPage('payment-methods')}><CreditCard size={15}/> Manage payment methods</button></section></div>}

if (import.meta.env.PROD && window.location.origin !== EXPECTED_SITE_ORIGIN) {
  document.getElementById('root').textContent = 'This YoMart admin build was created for a different website origin. Contact the deployment owner.';
} else {
  createRoot(document.getElementById('root')).render(<App/>);
}
